reference_solution:
import heapq
from collections import Counter
def topKFrequentWords(words, k):
    c = Counter(words)
    return heapq.nsmallest(k, c, key=lambda w: (-c[w], w))

brute_force_solution:
def topKFrequentWords(words, k):
    c = {}
    for w in words:
        c[w] = c.get(w, 0) + 1
    out = []
    for _ in range(k):
        best = None
        for w in c:
            if w in out:
                continue
            if best is None or c[w] > c[best] or (c[w] == c[best] and w < best):
                best = w
        out.append(best)
    return out

